296	package net.officefloor.hq.app.pool;
297	
298	import java.math.BigDecimal;
299	import java.math.RoundingMode;
300	import java.time.LocalDate;
301	import java.util.HashMap;
302	import java.util.List;
303	import java.util.Map;
304	import java.util.function.Function;
305	import java.util.stream.Collectors;
306	import net.officefloor.hq.app.Audit;
307	import net.officefloor.hq.app.person.Person;
308	import net.officefloor.hq.app.person.PersonRepository;
309	import net.officefloor.hq.app.sheet.SheetService;
310	import org.springframework.http.HttpStatus;
311	import org.springframework.stereotype.Service;
312	import org.springframework.transaction.annotation.Transactional;
313	import org.springframework.web.server.ResponseStatusException;
314	
315	/** The pools on a sheet: listed with their members, added, and given members. */
316	@Service
317	public class PoolService {
318	
319	    private static final BigDecimal MAX_SHARE = new BigDecimal("100.00");
320	
321	    /** How many pools deep a chain of pools may be, the pool that is a member of none counting as one. */
322	    private static final int MAX_DEPTH = 3;
323	
324	    /** A pool with its members in the order they were added, each with the person's name. */
325	    public record PoolWithMembers(Pool pool, List<Member> members) {
326	    }
327	
328	    /** A member with its name: the person's, or the member pool's. */
329	    public record Member(PoolMember member, String name) {
330	    }
331	
332	    private final PoolRepository pools;
333	    private final PoolMemberRepository members;
334	    private final PersonRepository people;
335	    private final SheetService sheets;
336	    private final Audit audit;
337	
338	    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
339	            SheetService sheets, Audit audit) {
340	        this.pools = pools;
341	        this.members = members;
342	        this.people = people;
343	        this.sheets = sheets;
344	        this.audit = audit;
345	    }
346	
347	    /** The sheet's pools in the order they were added, with their members. */
348	    @Transactional(readOnly = true)
349	    public List<PoolWithMembers> list(String sheetId) {
350	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
351	        Map<Long, String> names = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
352	                .collect(Collectors.toMap(Person::getId, Person::getName));
353	        Map<Long, String> poolNames = all.stream().collect(Collectors.toMap(Pool::getId, Pool::getName));
354	        Map<Long, List<Member>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
355	                .stream().map(m -> new Member(m, m.getMemberPoolId() != null ? poolNames.get(m.getMemberPoolId())
356	                        : names.get(m.getPersonId())))
357	                .collect(Collectors.groupingBy(m -> m.member().getPoolId()));
358	        return all.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
359	    }
360	
361	    /** Add a pool; refused when its name, trimmed, is blank or already a pool's on the sheet. */
362	    @Transactional
363	    public PoolWithMembers add(String sheetId, String user, String name) {
364	        String trimmed = name.strip();
365	        if (trimmed.isEmpty()) {
366	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A pool needs a name.");
367	        }
368	        sheets.lock(sheetId);
369	        if (pools.existsBySheetIdAndName(sheetId, trimmed)) {
370	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is already a pool by that name.");
371	        }
372	        Pool saved = pools.saveAndFlush(new Pool(sheetId, trimmed));
373	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + trimmed);
374	        return new PoolWithMembers(saved, List.of());
375	    }
376	
377	    /**
378	     * Add a person on the sheet to a pool with a share percent; refused when the share is not more than
379	     * 0.00 and at most 100.00 with two decimals, the to-date is before the from-date, or the person is
380	     * already in the pool.
381	     */
382	    @Transactional
383	    public PoolWithMembers addMember(String sheetId, String user, long poolId, long personId, BigDecimal share,
384	            LocalDate from, LocalDate to) {
385	        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
386	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
387	                    "A share is more than 0.00 and at most 100.00, with two decimals.");
388	        }
389	        refuseDates(from, to);
390	        sheets.lock(sheetId);
391	        Pool pool = pools.findBySheetIdAndId(sheetId, poolId)
392	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
393	        Person person = people.findById(personId).filter(p -> p.getSheetId().equals(sheetId))
394	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
395	        if (members.existsByPoolIdAndPersonId(poolId, personId)) {
396	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool.");
397	        }
398	        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
399	        members.saveAndFlush(new PoolMember(poolId, personId, scaled).during(from, to));
400	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
401	                + " name=" + person.getName() + " share=" + scaled.toPlainString() + dates(from, to));
402	        return list(sheetId).stream().filter(p -> p.pool().getId().equals(poolId)).findFirst().orElseThrow();
403	    }
404	
405	    /**
406	     * Add another pool on the sheet to a pool with a share percent; refused when the share is bad, the pool
407	     * would contain itself through any chain, the member pool is already a member of a pool, or the chain of
408	     * pools would be more than three deep; or the to-date is before the from-date.
409	     */
410	    @Transactional
411	    public PoolWithMembers addPoolMember(String sheetId, String user, long poolId, long memberPoolId,
412	            BigDecimal share, LocalDate from, LocalDate to) {
413	        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
414	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
415	                    "A share is more than 0.00 and at most 100.00, with two decimals.");
416	        }
417	        refuseDates(from, to);
418	        sheets.lock(sheetId);
419	        Pool pool = pools.findBySheetIdAndId(sheetId, poolId)
420	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
421	        Pool member = pools.findBySheetIdAndId(sheetId, memberPoolId)
422	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
423	        // Each member pool's parent, and each pool's member pools, across the sheet.
424	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
425	        Map<Long, Long> parents = new HashMap<>();
426	        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())) {
427	            if (m.getMemberPoolId() != null) parents.put(m.getMemberPoolId(), m.getPoolId());
428	        }
429	        for (Long up = pool.getId(); up != null; up = parents.get(up)) {
430	            if (up.equals(member.getId())) {
431	                throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot contain itself.");
432	            }
433	        }
434	        if (parents.containsKey(member.getId())) {
435	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already a member of a pool.");
436	        }
437	        if (depth(pool.getId(), parents) + height(member.getId(), parents) > MAX_DEPTH) {
438	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A chain of pools is at most three deep.");
439	        }
440	        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
441	        members.saveAndFlush(PoolMember.ofPool(poolId, memberPoolId, scaled).during(from, to));
442	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
443	                + " name=" + member.getName() + " share=" + scaled.toPlainString() + dates(from, to));
444	        return list(sheetId).stream().filter(p -> p.pool().getId().equals(poolId)).findFirst().orElseThrow();
445	    }
446	
447	    /** Refused when a membership's to-date is before its from-date. */
448	    private static void refuseDates(LocalDate from, LocalDate to) {
449	        if (from != null && to != null && to.isBefore(from)) {
450	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A to-date is not before the from-date.");
451	        }
452	    }
453	
454	    /** A membership's dates as audited: from=<date> and to=<date>, each only when given. */
455	    private static String dates(LocalDate from, LocalDate to) {
456	        return (from != null ? " from=" + from : "") + (to != null ? " to=" + to : "");
457	    }
458	
459	    /** How deep a pool is in its chain: 1 for a pool that is a member of none. */
460	    private static int depth(Long poolId, Map<Long, Long> parents) {
461	        int depth = 1;
462	        for (Long up = parents.get(poolId); up != null; up = parents.get(up)) depth++;
463	        return depth;
464	    }
465	
466	    /** How many pools deep the chain below a pool is, the pool itself counting as one. */
467	    private static int height(Long poolId, Map<Long, Long> parents) {
468	        int height = 1;
469	        for (Map.Entry<Long, Long> e : parents.entrySet()) {
470	            if (e.getValue().equals(poolId)) height = Math.max(height, 1 + height(e.getKey(), parents));
471	        }
472	        return height;
473	    }
474	}
