705	package net.officefloor.hq.app.crew;
706	
707	import java.util.List;
708	import java.util.Map;
709	import java.util.stream.Collectors;
710	import net.officefloor.hq.app.Audit;
711	import net.officefloor.hq.app.person.Person;
712	import net.officefloor.hq.app.person.PersonRepository;
713	import net.officefloor.hq.app.sheet.SheetService;
714	import org.springframework.http.HttpStatus;
715	import org.springframework.stereotype.Service;
716	import org.springframework.transaction.annotation.Transactional;
717	import org.springframework.web.server.ResponseStatusException;
718	
719	/** The crews on a sheet: listed with their lead and members, added, and given members. */
720	@Service
721	public class CrewService {
722	
723	    /** A crew with its lead's name and its members in the order they were added. */
724	    public record CrewWithMembers(Crew crew, String lead, List<Member> members) {
725	    }
726	
727	    /** A member with the person's name. */
728	    public record Member(CrewMember member, String name) {
729	    }
730	
731	    private final CrewRepository crews;
732	    private final CrewMemberRepository members;
733	    private final PersonRepository people;
734	    private final SheetService sheets;
735	    private final Audit audit;
736	
737	    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
738	            SheetService sheets, Audit audit) {
739	        this.crews = crews;
740	        this.members = members;
741	        this.people = people;
742	        this.sheets = sheets;
743	        this.audit = audit;
744	    }
745	
746	    /** The sheet's crews in the order they were added, with their lead and members. */
747	    @Transactional(readOnly = true)
748	    public List<CrewWithMembers> list(String sheetId) {
749	        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
750	        Map<Long, String> names = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
751	                .collect(Collectors.toMap(Person::getId, Person::getName));
752	        Map<Long, List<Member>> byCrew = members.findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId).toList())
753	                .stream().map(m -> new Member(m, names.get(m.getPersonId())))
754	                .collect(Collectors.groupingBy(m -> m.member().getCrewId()));
755	        return all.stream().map(c -> new CrewWithMembers(c, names.get(c.getLeadId()),
756	                byCrew.getOrDefault(c.getId(), List.of()))).toList();
757	    }
758	
759	    /**
760	     * Add a crew led by a person on the sheet; refused when its name, trimmed, is blank or already a crew's
761	     * on the sheet.
762	     */
763	    @Transactional
764	    public CrewWithMembers add(String sheetId, String user, String name, long leadId) {
765	        String trimmed = name.strip();
766	        if (trimmed.isEmpty()) {
767	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A crew needs a name.");
768	        }
769	        sheets.lock(sheetId);
770	        Person lead = people.findByIdAndSheetId(leadId, sheetId)
771	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
772	        if (crews.existsBySheetIdAndName(sheetId, trimmed)) {
773	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is already a crew by that name.");
774	        }
775	        Crew saved = crews.saveAndFlush(new Crew(sheetId, trimmed, lead.getId()));
776	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + trimmed
777	                + " lead=" + lead.getName());
778	        return new CrewWithMembers(saved, lead.getName(), List.of());
779	    }
780	
781	    /** Add a person on the sheet to a crew; refused when they lead it or are already in it. */
782	    @Transactional
783	    public CrewWithMembers addMember(String sheetId, String user, long crewId, long personId) {
784	        sheets.lock(sheetId);
785	        Crew crew = crews.findBySheetIdAndId(sheetId, crewId)
786	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew."));
787	        Person person = people.findByIdAndSheetId(personId, sheetId)
788	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
789	        if (crew.getLeadId().equals(personId)) {
790	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The lead is not a member of their own crew.");
791	        }
792	        if (members.existsByCrewIdAndPersonId(crewId, personId)) {
793	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the crew.");
794	        }
795	        members.saveAndFlush(new CrewMember(crewId, personId));
796	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
797	                + " name=" + person.getName());
798	        return list(sheetId).stream().filter(c -> c.crew().getId().equals(crewId)).findFirst().orElseThrow();
799	    }
800	
801	    /**
802	     * A person merged into another: the crews they lead are led by the other, and their memberships move to
803	     * the other, dropped where the other is already in the crew or leads it.
804	     */
805	    @Transactional
806	    public void merge(Person from, Person into) {
807	        for (Crew crew : crews.findByLeadIdOrderByIdAsc(from.getId())) {
808	            crew.leadBy(into.getId());
809	            crews.save(crew);
810	            members.findByCrewIdInOrderByIdAsc(List.of(crew.getId())).stream()
811	                    .filter(m -> m.getPersonId().equals(into.getId())).forEach(members::delete);
812	        }
813	        crews.flush();
814	        for (CrewMember member : members.findByPersonIdOrderByIdAsc(from.getId())) {
815	            Crew crew = crews.findById(member.getCrewId()).orElseThrow();
816	            if (crew.getLeadId().equals(into.getId())
817	                    || members.existsByCrewIdAndPersonId(member.getCrewId(), into.getId())) {
818	                members.delete(member);
819	            } else {
820	                member.moveTo(into.getId());
821	                members.save(member);
822	            }
823	            members.flush();
824	        }
825	    }
826	
827	    /** A person leaving the sheet: their memberships go, and so do the crews they lead with their members. */
828	    @Transactional
829	    public void leave(Person person) {
830	        members.deleteAll(members.findByPersonIdOrderByIdAsc(person.getId()));
831	        List<Crew> led = crews.findByLeadIdOrderByIdAsc(person.getId());
832	        members.deleteAll(members.findByCrewIdInOrderByIdAsc(led.stream().map(Crew::getId).toList()));
833	        crews.deleteAll(led);
834	        members.flush();
835	        crews.flush();
836	    }
837	}
