  const all = new Map(shares.map((m) => [m.id, total > 0n ? cut(pot, BigInt(m.share), total) : 0n]));
  const smallest = withCut.reduce<(typeof withCut)[number] | undefined>((best, m) => {
    const c = all.get(m.id)!;
    return c > 0n && (best === undefined || c <= all.get(best.id)!) ? m : best;
  }, undefined) ?? withCut[withCut.length - 1];
  if (smallest) {
    const remainder = pot - [...all.values()].reduce((sum, c) => sum + c, 0n);
    all.set(smallest.id, all.get(smallest.id)! + remainder);
  }
  return all;
}

